// FSM as an arbiter: access to a resource controlled by three requesting
// devices. The FSM stays in state A as long as there are no requests.
// When one or more request occurs, the FSM decides which device receives
// a grant to use the resource and changes to a state that sets that
// device's g[i] signal to 1. Each g[i] is an output from the FSM.
// There is a priority system, in that device 0 has a higher priority
// than device 1, and device 2 has the lowest priority. Hence, for
// example, device 2 will only receive a grant if it is the only device
// making a request when the FSM is in state A. Once a device, i, is
// given a grant by the FSM, that device continues to receive the grant
// as long as its request, r[i] = 1.
module TopModule (
    input  clk,
    input  resetn,
    input  [2:0] r,
    output [2:0] g
);
    reg [1:0] state, nextstate;
    always @* begin
        case (state)
            2'd0: nextstate = (r == 3'b000) ? 2'd0 : ((r & 3'b001) != 0) ? 2'd1 : 2'd2;
            2'd1: nextstate = (r & 3'b001) != 0 ? 2'd1 : 2'd0;
            2'd2: nextstate = (r & 3'b010) != 0 ? 2'd2 : 2'd0;
            default: nextstate = 2'd0;
        endcase
    end
    always @(posedge clk) begin
        if (!resetn) state <= 2'd0;
        else state <= nextstate;
    end
    always @* begin
        case (state)
            2'd0: g = 3'b000;
            2'd1: g = {1'b1, 1'b0, 1'b0};
            2'd2: g = {1'b0, 1'b1, 1'b0};
            default: g = 3'b000;
        endcase
    end
endmodule

