module TopModule(
    input  clk,
    input  resetn,
    input  [2:0] r,
    output [2:0] g
);
    // State register and combinational next state logic
    reg [2:0] state, nextstate;
    always @(*) begin
        case (state)
            // State A
            3'b000: nextstate = (r == 3'b000) ? 3'b000 :
                                (r[0]     ) ? 3'b001 :
                                (r[1]     ) ? 3'b010 : 3'b011;
            // State B
            3'b001: nextstate = (r[0]     ) ? 3'b001 :
                                (r[0] == 0) ? 3'b000 : 3'b011;
            // State C
            3'b010: nextstate = (r[1]     ) ? 3'b010 :
                                (r[1] == 0) ? 3'b000 : 3'b001;
            // State D
            3'b011: nextstate = (r == 3'b000) ? 3'b011 :
                                (r[0]     ) ? 3'b001 :
                                (r[1]     ) ? 3'b010 : 3'b000;
            default: nextstate = 3'b000;
        endcase
    end
    // State register feedback
    always @(posedge clk) begin
        if (!resetn) state <= 3'b000;
        else        state <= nextstate;
    end
    // Output logic, one per state, as a combinational register
    reg [2:0] g_reg;
    always @(*) begin
        case (state)
            3'b000: g_reg = 3'b000;
            3'b001: g_reg = 3'b001;
            3'b010: g_reg = 3'b010;
            3'b011: g_reg = 3'b011;
            default: g_reg = 3'b000;
        endcase
    end
    // Continuous assignment output (same as the register above, but in
    // one single combinational register, instead of one per state).
    assign g = g_reg;
endmodule

